using Archy.Features.Health.HealthSnapshots;
namespace Archy.Features.Health.CalculateArchitectureHealth;
/// <summary>Builds explainable weighted health components and caps the score whenever introduced blocking violations exist.</summary>
public sealed class ArchitectureHealthCalculator(ArchitectureHealthWeights weights):IArchitectureHealthCalculator { public HealthSnapshotFact Calculate(ArchitectureHealthInput input){ArgumentNullException.ThrowIfNull(input);if(input.GraphRevision<1||input.IntroducedBlockingViolations<0||input.LegacyViolations<0||input.ActiveDuplicateFindings<0||!Probability(input.DocumentationDebtRatio)||!Probability(input.DecisionResolutionDebt)||input.ResolutionDecisionIds is null||!Weights(weights))throw new ArgumentException("Architecture health requires bounded component inputs and normalized non-negative weights.",nameof(input));var architecture=Math.Min(1d,(input.IntroducedBlockingViolations+input.LegacyViolations)/10d);var duplicate=Math.Min(1d,input.ActiveDuplicateFindings/10d);var components=new[]{Component("architecture",architecture,weights.Architecture,$"{{\"introducedBlocking\":{input.IntroducedBlockingViolations},\"legacy\":{input.LegacyViolations}}}"),Component("duplicates",duplicate,weights.Duplicates,$"{{\"active\":{input.ActiveDuplicateFindings}}}"),Component("documentation",input.DocumentationDebtRatio,weights.Documentation,"{}"),Component("decisions",input.DecisionResolutionDebt,weights.Decisions,"{}")};var score=Math.Round(100d*(1d-components.Sum(x=>x.WeightedContribution)),2,MidpointRounding.AwayFromZero);if(input.IntroducedBlockingViolations>0)score=Math.Min(score,49d);return new(input.GraphRevision,"architecture-health/v1",score,components,input.ResolutionDecisionIds);} static HealthMetricComponentFact Component(string key,double raw,double weight,string detail)=>new(key,raw,weight,Math.Round(raw*weight,6),detail);static bool Probability(double x)=>double.IsFinite(x)&&x is>=0 and<=1;static bool Weights(ArchitectureHealthWeights w)=>w is not null&&new[]{w.Architecture,w.Duplicates,w.Documentation,w.Decisions}.All(x=>double.IsFinite(x)&&x>=0)&&Math.Abs(w.Architecture+w.Duplicates+w.Documentation+w.Decisions-1d)<.000001d;}
